#include <stdio.h>

void show(int x) {
    printf("碗里是 %d\n", x);
}

void show_double(int x) {
    printf("翻倍是 %d\n", x * 2);
}

void each(int a[], int n, void (*visit)(int)) {
    for (int i = 0; i < n; i++) {
        visit(a[i]);
    }
}

int main(void) {
    int bowl[{n}];

    for (int i = 0; i < {n}; i++) {
        if (scanf("%d", &bowl[i]) != 1) {
            return 1;
        }
    }

    each(bowl, {n}, show);
    each(bowl, {n}, show_double);
    return 0;
}
